<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
type Request=(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<any>;
const props=defineProps<{platform:boolean;request:Request;readonly:boolean}>();
const busy=ref(false),error=ref(''),notice=ref(''),data=ref<any>({tasks:[],versions:[],releases:[]}),sensitive=ref(''),strict=ref(true),policyVersion=ref(0);
const prompt=reactive({taskType:'CUSTOMER_SUMMARY',title:'',instruction:''});
const rule=reactive({source:'',output:''}),ruleResult=ref<any>(null);
const taskNames=ref<Record<string,string>>({});
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function load(){if(props.platform){data.value=await props.request('/platform/ai/prompts');taskNames.value=Object.fromEntries(data.value.tasks.map((t:any)=>[t.id,t.name]));}else{const p=await props.request('/ai/quality-settings');sensitive.value=p.sensitiveTerms.join('\n');strict.value=p.strictFacts;policyVersion.value=p.version;}}
async function savePolicy(){await run(async()=>{await props.request('/ai/quality-settings','PUT',{sensitiveTerms:sensitive.value.split('\n').map(x=>x.trim()).filter(Boolean),strictFacts:strict.value,expectedVersion:policyVersion.value});await load();notice.value='敏感信息策略已保存；之前的发送确认和业务草稿需重新生成。';});}
async function createPrompt(){await run(async()=>{await props.request('/platform/ai/prompts','POST',prompt);prompt.title='';prompt.instruction='';await load();notice.value='新版本已保存，尚未发布。请选择版本并配置灰度范围。';});}
function use(row:any){Object.assign(prompt,{taskType:row.taskType,title:row.title+' · 新版',instruction:row.instruction});}
async function release(row:any,rollback=false){await run(async()=>{await props.request('/platform/ai/releases/'+row.taskType+(rollback?'/rollback':''),rollback?'POST':'PUT',{promptId:row.promptId,enabled:row.enabled,rolloutPercent:Number(row.rolloutPercent),expectedVersion:row.version});await load();notice.value=rollback?'已回滚提示词版本，仅影响后续调用与未保存草稿。':'发布范围已保存。企业使用固定灰度分组，关闭后停止后续调用。';});}
async function testRule(){await run(async()=>{ruleResult.value=await props.request('/platform/ai/rule-test','POST',rule);});}
onMounted(()=>run(load));
</script>
<template>
 <section class="p8-quality">
  <div v-if="error" class="feedback bad" role="alert">{{error}}</div><div v-if="notice" class="feedback" role="status">{{notice}}</div>
  <template v-if="platform">
   <section class="card panel"><div class="title"><h2>提示词与灰度发布</h2><button class="text-button" :disabled="busy" @click="run(load)">刷新发布配置</button></div><p class="hint">每个版本创建后保持不变。新增场景默认关闭；先选择少量企业试用，再扩大到 100%。灰度按企业固定分组。</p><div class="table-scroll"><table><thead><tr><th>场景</th><th>发布版本</th><th>开放 / 灰度</th><th>操作</th></tr></thead><tbody><tr v-for="r in data.releases" :key="r.taskType"><td>{{taskNames[r.taskType]}}<small>配置版本 {{r.version}}</small></td><td><select v-model="r.promptId" :aria-label="taskNames[r.taskType]+'发布版本'" :disabled="busy"><option v-for="v in data.versions.filter((v:any)=>v.taskType===r.taskType)" :key="v.id" :value="v.id">{{v.title}} · {{v.id.slice(-6)}}</option></select></td><td><label class="check"><input v-model="r.enabled" type="checkbox" :disabled="busy" :aria-label="taskNames[r.taskType]+'开放'"/>开放</label><label>覆盖企业比例（%）<input v-model.number="r.rolloutPercent" type="number" min="0" max="100" :disabled="busy" :aria-label="taskNames[r.taskType]+'灰度比例'"/></label></td><td><button class="text-button" :disabled="busy" @click="release(r)">保存发布</button><button class="text-button" :disabled="busy||!r.previousPromptId" @click="release(r,true)">回滚上一版</button></td></tr></tbody></table></div></section>
   <form class="card panel" @submit.prevent="createPrompt"><h2>创建提示词版本</h2><div class="fields"><label>提示词场景<select v-model="prompt.taskType" :disabled="busy"><option v-for="t in data.tasks" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>版本名称<input v-model="prompt.title" maxlength="100" required :disabled="busy"/></label><label class="wide">任务指引<textarea v-model="prompt.instruction" rows="5" maxlength="4000" required :disabled="busy"/></label></div><p class="hint">权限、脱敏、人工确认和费用控制由服务端执行，提示词不能改变业务权限。</p><button class="btn secondary" :disabled="busy">创建未发布版本</button><details><summary>查看历史版本并复制</summary><div v-for="v in data.versions" :key="v.id" class="version"><strong>{{taskNames[v.taskType]}} · {{v.title}}</strong><p>{{v.instruction}}</p><button type="button" class="text-button" :disabled="busy" @click="use(v)">复制为新版本</button></div></details></form>
   <form class="card panel" @submit.prevent="testRule"><h2>离线质量规则评估</h2><p class="hint">使用人工编写的虚拟素材与待测输出检查敏感信息、日期和金额。不调用模型，不产生供应商费用，不代表真实模型质量验收。</p><div class="fields"><label>已知事实素材<textarea v-model="rule.source" rows="4" maxlength="12000" required :disabled="busy"/></label><label>待测输出<textarea v-model="rule.output" rows="4" maxlength="12000" required :disabled="busy"/></label></div><button class="btn secondary" :disabled="busy">运行离线规则检查</button><div v-if="ruleResult" class="result"><strong>{{({PASS:'规则检查通过',REVIEW:'需要人工复核',BLOCKED:'策略阻断'} as Record<string,string>)[ruleResult.result.status]}}</strong><ul><li v-for="f in ruleResult.result.findings" :key="f">{{f}}</li></ul><p>未调用供应商。业务可用性请结合企业端的主管复核及质量评分判断。</p></div></form>
  </template>
  <form v-else class="card panel" @submit.prevent="savePolicy"><h2>敏感信息与事实检查</h2><p class="hint">系统默认隐藏联系方式、证件和凭据。可添加本企业的内部项目代号、保密产品名等词语，每行一个，最多 20 个。不要把 API Key 填在这里。</p><label>企业敏感词<textarea v-model="sensitive" rows="5" :disabled="busy||readonly" placeholder="每行一个，2–64 个字符"/></label><label class="check"><input v-model="strict" type="checkbox" :disabled="busy||readonly"/>检查输出中来源未出现的日期、金额和比例</label><p class="hint">命中敏感词的输出禁止采纳；可疑事实需要主管复核。规则无法识别所有幻觉，使用前仍需核实。</p><button class="btn secondary" :disabled="busy||readonly">保存敏感信息策略</button></form>
 </section>
</template>
<style scoped>
.p8-quality{display:flex;flex-direction:column;gap:20px;min-width:0}.panel{padding:24px;min-width:0}.panel h2{font-size:18px;margin-bottom:16px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:16px 0}label{display:flex;flex-direction:column;gap:8px;font-size:12px}.wide{grid-column:1/-1}input,select,textarea{padding:10px;max-width:100%;width:100%;box-sizing:border-box;border:1px solid rgba(142,171,216,.3);border-radius:8px;background:rgba(5,14,29,.65);color:inherit;font:inherit}.check{flex-direction:row;align-items:center;margin:14px 0}.check input{width:auto}.hint,p,small{font-size:12px;color:var(--text-muted,#9bacc6);line-height:1.8}td{vertical-align:top;min-width:160px}td small{display:block}.title{display:flex;justify-content:space-between;gap:16px;align-items:center}.version{padding:16px 0;border-bottom:1px solid #30435c;font-size:13px}.version p{white-space:pre-wrap}.feedback,.result{padding:14px;border:1px solid #477e84;border-radius:8px;font-size:13px}.bad{border-color:#b96977;color:#ffbac6}details{margin-top:20px}summary{cursor:pointer;font-size:13px}@media(max-width:800px){.fields{grid-template-columns:1fr}.wide{grid-column:auto}.panel{padding:16px}}
</style>
